import { LinearGradient } from 'expo-linear-gradient';
import { useState, type ReactNode } from 'react';
import { Image, StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { Defs, G, LinearGradient as SvgGradient, Path, Rect, Stop } from 'react-native-svg';

/** Card colors are unchanged. (The reference screenshots are olive: ['#46611E', '#36501A', '#264010', '#1B3109', '#112206'].) */
export const TAWSELA_CARD_GRADIENT = ['#0C7D58', '#056244', '#014835', '#012B20', '#011B14'] as const;
const TAWSELA_CARD_LOCATIONS = [0, 0.26, 0.52, 0.8, 1] as const;
export const CARD_INK = '#FDFAEB';

/** Card shape measured from the reference card screenshots: width / height, and corner radius as a share of the width. */
const CARD_RATIO = 1.587;
const CARD_RADIUS = 0.037;

/** Back logo opacity. */
const BACK_LOGO_OPACITY = 0.75;

/** Tawsela logo embedded in this file as base64 (no asset file needed). The front copy has its left/right edges faded out. */
const LOGO_FRONT_URI = 'data:image/png;base64,';
const LOGO_BACK_URI = 'data:image/png;base64,';
const LOGO_RATIO = 1000 / 390;

/** Tawsela logo on both card faces: top-left on the front, big and cropped at the bottom-left on the back. */
export function CardLogo({ side = 'front' }: { side?: 'front' | 'back' }) {
  return (
    <Image
      pointerEvents="none"
      source={{ uri: side === 'front' ? LOGO_FRONT_URI : LOGO_BACK_URI }}
      resizeMode="contain"
      style={side === 'front' ? styles.logoFront : styles.logoBack}
    />
  );
}

export function CardSurface({
  bg = TAWSELA_CARD_GRADIENT,
  children,
  style,
  logo,
}: {
  bg?: readonly [string, string, ...string[]];
  children?: ReactNode;
  style?: StyleProp<ViewStyle>;
  logo?: 'front' | 'back';
}) {
  const [box, setBox] = useState({ w: 0, h: 0 });
  const ratio = box.w > 0 && box.h > 0 ? box.w / box.h : CARD_RATIO;
  const radius = box.w > 0 ? box.w * CARD_RADIUS : 14;
  /* Same as a CSS `linear-gradient(135deg, ...)`: true 45 degree lines whatever the card shape. */
  const start = { x: 0.25 - 0.25 / ratio, y: 0.25 - 0.25 * ratio };
  const end = { x: 0.75 + 0.25 / ratio, y: 0.75 + 0.25 * ratio };
  return (
    <View
      style={[styles.card, { borderRadius: radius }, style]}
      onLayout={(e) => {
        const { width, height } = e.nativeEvent.layout;
        if (width > 0 && height > 0) setBox({ w: width, h: height });
      }}
    >
      <LinearGradient
        colors={bg}
        locations={bg.length === TAWSELA_CARD_LOCATIONS.length ? TAWSELA_CARD_LOCATIONS : undefined}
        start={start}
        end={end}
        style={StyleSheet.absoluteFill}
      />
      <View pointerEvents="none" style={styles.topLine} />
      {logo ? <CardLogo side={logo} /> : null}
      {children}
    </View>
  );
}

/** Silver EMV contact chip with the contactless symbol next to it (pass wave={false} to hide it). */
export function CardChip({ wave = true }: { wave?: boolean }) {
  return (
    <View style={styles.chipRow}>
      <Svg width={54.4} height={38.4} viewBox="0 0 100 72">
        <Defs>
          <SvgGradient id="tawselaChipSilver" x1="0" y1="0" x2="1" y2="1">
            <Stop offset="0" stopColor="#F7F7F7" />
            <Stop offset="0.55" stopColor="#E2E2E2" />
            <Stop offset="1" stopColor="#B9B9B9" />
          </SvgGradient>
        </Defs>
        <Rect x={0} y={0} width={100} height={72} rx={9} fill="url(#tawselaChipSilver)" />
        <G fill="none" stroke="#4A4A4A" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
          <Path d="M0 26H23L28 21V12L36 0" />
          <Path d="M100 26H77L72 21V12L64 0" />
          <Path d="M0 46H23L28 51V60L36 72" />
          <Path d="M100 46H77L72 51V60L64 72" />
          <Rect x={28} y={21} width={44} height={30} />
          <Path d="M23 26V46M77 26V46" />
        </G>
      </Svg>
      {wave ? <CardWave /> : null}
    </View>
  );
}

