const styles = StyleSheet.create({
  card: { width: '100%', aspectRatio: CARD_RATIO, alignSelf: 'center', padding: 22, overflow: 'hidden', justifyContent: 'space-between', borderWidth: 1, borderColor: 'rgba(255,255,255,0.07)' },
  chipRow: { flexDirection: 'row', alignItems: 'center', gap: 14 },
  topLine: { position: 'absolute', top: 0, left: 0, right: 0, height: 1, backgroundColor: 'rgba(255,255,255,0.08)' },
  logoFront: { position: 'absolute', top: '1%', left: '-1.5%', width: '34.6%', aspectRatio: LOGO_RATIO },
  logoBack: { position: 'absolute', left: '-7.7%', bottom: '-21.3%', width: '115.4%', aspectRatio: LOGO_RATIO, opacity: BACK_LOGO_OPACITY },
});
